def a_n_recurrence(n):
    if n == 1:
        return 10

    # We calculate a_n based on a_{n-1}
    # a_{n+1} = 6a_n - 2^{n+2} - 3^{n+1} + 5
    # a_n = 6a_{n-1} - 2^{n+1} - 3^n + 5  (where n is the index we are calculating)

    a_prev = a_n_recurrence(n-1)

    return 6 * a_prev - (2**(n+1)) - (3**n) + 5

def a_n_closed_form(n):
    return 6**n + 2**n + 3**n - 1

# Test for n=1 to 4
tests = list(range(1, 5))
results = {}

for n in tests:
    recurrence_val = a_n_recurrence(n)
    closed_form_val = a_n_closed_form(n)

    is_equal = (recurrence_val == closed_form_val)
    results[n] = (recurrence_val, closed_form_val, is_equal)

print("n | Recurrence Value | Closed Form Value | Match")
for n, (r, c, m) in results.items():
    print(f"{n} | {r} | {c} | {m}")

import math

def prime_factorization(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def calculate_an(n):
    # a_n = 6^n + 2^n + 3^n - 1
    return 6**n + 2**n + 3**n - 1

print("n | a_n | Prime Factors")
for n in range(1, 7):
    a_n = calculate_an(n)
    factors = prime_factorization(a_n)
    print(f"{n:^1} | {a_n:^5} | {sorted(list(factors))}")
